import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Creación de personajes y orígenes","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/characters/character-creation.md","filePath":"es/game-design/characters/character-creation.md"}'),r={name:"es/game-design/characters/character-creation.md"};function o(t,e,c,d,l,p){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="character-creation-backgrounds" tabindex="-1">Creación de personajes y orígenes <a class="header-anchor" href="#character-creation-backgrounds" aria-label="Enlace permanente a &quot;Creación de personajes y orígenes&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las preguntas abiertas permanecen Sin resolver. Las decisiones citadas con estado Aceptado conservan su alcance existente. <strong>Implementación/disponibilidad:</strong> no hay cambios en gameplay ni en configuración de ejecución; no se ha establecido que este rediseño esté activo. <strong>Verificación:</strong> revisión documental, no prueba de juego; aquí no se establece la disponibilidad actual. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/characters/character-creation.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/characters/progression.html">Progresión del personaje</a></p><h2 id="starting-histories-not-permanent-classes" tabindex="-1">Historias iniciales, no clases permanentes <a class="header-anchor" href="#starting-histories-not-permanent-classes" aria-label="Enlace permanente a &quot;Historias iniciales, no clases permanentes&quot;">​</a></h2><p>Explorar la creación mediante <strong>Origen → Competencias iniciales → Técnicas/conocimientos iniciales</strong>. Una competencia importante elegida podría comenzar alrededor de <strong>20 de habilidad</strong>, con los fundamentos ya conocidos y sin un requisito inicial de instrucción por un NPC. Esta es la excepción a <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html#learning-skills-from-zero-and-teachers">aprender una disciplina desconocida desde cero</a>.</p><p>Son historias y conjuntos de competencias, no clases permanentes. Los personajes siguen siendo libres de desarrollarse en otras direcciones. Conservar la creación clásica solo cuando sirva a este objetivo; aquí no se determina ninguna configuración exacta, cantidad de opciones ni distribución de estadísticas iniciales.</p><h2 id="illustrative-backgrounds" tabindex="-1">Ejemplos de orígenes <a class="header-anchor" href="#illustrative-backgrounds" aria-label="Enlace permanente a &quot;Ejemplos de orígenes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Historia de ejemplo</th><th>Competencias candidatas</th><th>Conocimiento inicial candidato</th></tr></thead><tbody><tr><td>Aprendiz de cazador</td><td>Archery, Tracking, Animal Lore</td><td>Preparación básica de presas en el campo</td></tr><tr><td>Aprendiz de taller</td><td>Carpentry, Tinkering</td><td>Ensambles básicos</td></tr><tr><td>Sanador de aldea</td><td>Healing, Anatomy</td><td>Conocimiento médico básico</td></tr></tbody></table><p>Estos ejemplos no aprueban una lista exhaustiva, valores exactos por conjunto, objetos gratuitos, reputación ni acceso automático a todas las técnicas. Las <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">habilidades</a> gobiernan la capacidad; las <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">técnicas</a> siguen siendo conocimiento aprendido por separado.</p><h2 id="experience-and-authority-constraints" tabindex="-1">Restricciones de experiencia y autoridad <a class="header-anchor" href="#experience-and-authority-constraints" aria-label="Enlace permanente a &quot;Restricciones de experiencia y autoridad&quot;">​</a></h2><p>La creación debería ofrecer una identidad útil de inmediato y explicar que el desarrollo futuro permanece abierto. La interfaz debería distinguir el conocimiento inicial de la capacidad numérica; no debería prometer sistemas sin descubrir ni presentar los ejemplos como clases definitivas.</p><p>El cliente expresa el origen y las competencias elegidas (USER INTENT). El servidor debe validar la elegibilidad y conceder las estadísticas, habilidades y conocimientos reales (AUTHORITATIVE SERVER STATE), publicar los valores aprobados (SYNCHRONIZED STATE) y dejar que el cliente muestre el resultado (CLIENT PRESENTATION). Esto aplica la autoridad existente del servidor; no se seleccionan paquetes, una nueva implementación de interfaz ni un esquema de guardado.</p><h2 id="legacy-reconciliation" tabindex="-1">Conciliación con el sistema heredado <a class="header-anchor" href="#legacy-reconciliation" aria-label="Enlace permanente a &quot;Conciliación con el sistema heredado&quot;">​</a></h2><p>La creación existente tiene totales de estadísticas, límites por habilidad, habilidades iniciales permitidas y concesiones de objetos; no representa el modelo propuesto de orígenes. El valor 120 en un total de habilidades iniciales no equivale a un límite de 120 para una sola habilidad.</p><p>Una implementación futura debe conciliar deliberadamente los personajes existentes, las opciones de creación del cliente y la validación del servidor. Este lote no cambia protocolos de cliente/servidor, personajes actuales ni configuración de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><ul><li>¿Cuántas opciones de origen/competencia habrá y cuáles pueden combinarse?</li><li>Valores iniciales exactos y si toda competencia elegida comienza cerca de 20.</li><li>Valores iniciales de estadísticas, límite total y rangos individuales; la <a href="/Syrolands-Public/es/game-design/characters/stats.html">dirección de las estadísticas</a> sigue separada.</li><li>Si los orígenes conceden técnicas, objetos o reputación, y su custodia/persistencia.</li><li>Disponibilidad y costes de maestros para disciplinas posteriores y protección frente al abuso de creación/enseñanza.</li><li>Redistribución, olvido o nueva elección de una historia, si se admite.</li><li>Conversión de personajes heredados y cuándo importan los personajes de producción existentes.</li></ul><p>Estas preguntas permanecen Sin resolver; los conjuntos de ejemplo no cubren esas lagunas.</p>',18)])])}const h=a(r,[["render",o]]);export{m as __pageData,h as default};
